# DOM id renames to {area}-{entity}-{action}, applied by rename-ids.ts (rename-testids.ts's header
# has the syntax and the rebase recipe). Ids that already follow the convention keep their names.
# The first matching line wins.
#
# URL fragment targets are bookmarked, so they keep their names: the /api TOC anchors and deep
# links, which OnThisPage navigates to.
authentication -> keep
capabilities -> keep
choose-your-workflow -> keep
workflow-<id> -> keep
# AdvancedGroup's `id` prop is the filter tree's node id, not a DOM id.
root -> keep
# TabItem copies Skeleton's own tab ids so Skeleton's content panel finds it; PR 14 retires it.
tabs:s5:<part> -> keep

